#include <string>
#include <vector>

double evaluateRpn(const std::vector<std::string>& tokens)
{
    std::vector<double> stack{};
    for (const std::string& token : tokens)
    {
        if (token == "+" || token == "-" || token == "*" || token == "/")
        {
            const double right{ stack.back() };
            stack.pop_back();
            const double left{ stack.back() };
            stack.pop_back();
            if (token == "+") stack.push_back(left + right);
            else if (token == "-") stack.push_back(left - right);
            else if (token == "*") stack.push_back(left * right);
            else stack.push_back(left / right);
        }
        else
        {
            stack.push_back(std::stod(token));
        }
    }
    return stack.back();
}

unitTests:
TEST("a single number") { CHECK_NEAR(evaluateRpn({ "42" }), 42.0, 1e-9); }
TEST("one operator") { CHECK_NEAR(evaluateRpn({ "3", "4", "+" }), 7.0, 1e-9); }
TEST("order matters for - and /") { CHECK_NEAR(evaluateRpn({ "10", "4", "-" }), 6.0, 1e-9); CHECK_NEAR(evaluateRpn({ "9", "2", "/" }), 4.5, 1e-9); }
TEST("chained") { CHECK_NEAR(evaluateRpn({ "3", "4", "+", "2", "*" }), 14.0, 1e-9); }
TEST("a longer expression") { CHECK_NEAR(evaluateRpn({ "5", "1", "2", "+", "4", "*", "+", "3", "-" }), 14.0, 1e-9); }

